script:
document.addEventListener('DOMContentLoaded', function () {
  const barsContainer = document.getElementById('amplitude-bars');
  const barsCount = 50;
  for (let i = 0; i < barsCount; i++) {
    const bar = document.createElement('div');
    bar.className = 'amplitude-bar';
    bar.style.height = '0px';
    barsContainer.appendChild(bar);
  }

  const visualizer = document.getElementById('visualizer');
  const micSelect = document.getElementById('mic-select');
  const testButton = document.getElementById('test-button');
  const recordingControls = document.getElementById('recording-controls');
  const playButton = document.getElementById('play-button');
  const pauseButton = document.getElementById('pause-button');
  const stopRecordingButton = document.getElementById('stop-recording-button');
  const restartButton = document.getElementById('restart-button');
  const shareButton = document.getElementById('share-button');
  const recordingProgress = document.getElementById('recording-progress');
  const statusMessage = document.getElementById('status-message');
  const recordingInstructions = document.getElementById('recording-instructions');
  const amplitudeBars = document.querySelectorAll('.amplitude-bar');
  const audioPlayerContainer = document.getElementById('audio-player-container');
  const audioPlayer = document.getElementById('audio-player');

  const addReviewBtn = document.getElementById('add-review-btn');
  const reviewForm = document.getElementById('review-form');
  const submitReviewBtn = document.getElementById('submit-review-btn');
  const cancelReviewBtn = document.getElementById('cancel-review-btn');

  const micNameEl = document.getElementById('mic-name');
  const gainControlEl = document.getElementById('gain-control');
  const channelsEl = document.getElementById('channels');
  const echoCancellationEl = document.getElementById('echo-cancellation');
  const latencyEl = document.getElementById('latency');
  const noiseSuppressionEl = document.getElementById('noise-suppression');
  const sampleRateEl = document.getElementById('sample-rate');
  const sampleSizeEl = document.getElementById('sample-size');
  const volumeEl = document.getElementById('volume');
  const qualityRatingEl = document.getElementById('quality-rating');

  let audioContext;
  let microphone;
  let analyser;
  let mediaRecorder;
  let audioChunks = [];
  let recordingStartTime;
  let recordingTimer;
  let audioBlob;
  let audioUrl;
  let audioElement;
  let currentState = 'idle';
  let recordingStopped = false;
  let recordingDuration = 5000;
  let audioStream;
  let devicesEnumerated = false;

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    updateStatusMessage('danger', 'Your browser does not support microphone access. Please use a modern browser like Chrome, Firefox, or Edge.');
    testButton.disabled = true;
    return;
  }

  function updateStatusMessage(type, message) {
    statusMessage.className = 'status-message alert-' + (type || 'info');

    let iconClass = 'bi-info-circle-fill';
    if (type === 'success') iconClass = 'bi-check-circle-fill';
    if (type === 'warning') iconClass = 'bi-exclamation-triangle-fill';
    if (type === 'danger') iconClass = 'bi-x-circle-fill';
    if (type === 'recording') iconClass = 'recording-pulse';

    let displayMessage = message;
    if (type === 'recording') {
      displayMessage = `<span class="recording-pulse"></span>${message}`;
    } else {
      displayMessage = `<div class="status-step"><span class="status-icon"><i class="bi ${iconClass}"></i></span><span>${message}</span></div>`;
    }

    statusMessage.innerHTML = displayMessage;

    if (type === 'recording') {
      recordingInstructions.classList.remove('d-none');
    } else {
      recordingInstructions.classList.add('d-none');
    }
  }

  function enumerateAudioDevices() {
    if (devicesEnumerated) {
      return Promise.resolve();
    }

    return navigator.mediaDevices.enumerateDevices()
      .then(devices => {
        const audioInputDevices = devices.filter(device => device.kind === 'audioinput');

        if (audioInputDevices.length === 0) {
          updateStatusMessage('warning', 'No microphone detected. Please connect a microphone and refresh the page.');
          testButton.disabled = true;
          return Promise.reject('No microphones found');
        }

        populateMicSelect(audioInputDevices);
        devicesEnumerated = true;
        return Promise.resolve();
      })
      .catch(error => {
        console.error('Error enumerating devices:', error);
        updateStatusMessage('danger', 'Error accessing media devices. Please ensure you have given permission to access your microphone.');
        throw error;
      });
  }

  function populateMicSelect(audioInputDevices) {
    micSelect.innerHTML = '';
    audioInputDevices.forEach((device, index) => {
      const option = document.createElement('option');
      option.value = device.deviceId;
      option.text = device.label || `Microphone ${index + 1}`;
      micSelect.appendChild(option);
    });

    micSelect.disabled = false;
  }

  const canvasCtx = visualizer.getContext('2d');

  testButton.addEventListener('click', function () {
    if (microphone) {
      stopMicrophone();
      resetUI();
      return;
    }

    currentState = 'detecting';
    updateStatusMessage('info', 'Requesting microphone access. Please allow access when prompted.');

    const constraints = {
      audio: {
        echoCancellation: true,
        noiseSuppression: true,
        autoGainControl: true
      }
    };

    navigator.mediaDevices.getUserMedia(constraints)
      .then(stream => {
        audioStream = stream;

        return navigator.mediaDevices.enumerateDevices()
          .then(devices => {
            const audioInputDevices = devices.filter(device => device.kind === 'audioinput');
            populateMicSelect(audioInputDevices);
            devicesEnumerated = true;
            return stream;
          });
      })
      .then(stream => {
        if (micSelect.value && micSelect.value !== stream.getAudioTracks()[0].getSettings().deviceId) {
          stream.getTracks().forEach(track => track.stop());

          const newConstraints = {
            audio: {
              deviceId: {exact: micSelect.value},
              echoCancellation: true,
              noiseSuppression: true,
              autoGainControl: true
            }
          };

          return navigator.mediaDevices.getUserMedia(newConstraints);
        }
        return stream;
      })
      .then(stream => {
        audioStream = stream;

        initAudioContext();

        currentState = 'recording';
        recordingStopped = false;
        updateStatusMessage('recording', '<strong>Recording in progress: </strong> Testing your microphone and recording your voice.');

        analyser = audioContext.createAnalyser();
        analyser.fftSize = 2048;

        microphone = audioContext.createMediaStreamSource(stream);
        microphone.connect(analyser);

        visualize();

        testButton.innerHTML = '<i class="bi bi-x-circle-fill me-2"></i>Cancel test';

        recordingControls.classList.remove('d-none');

        displayMicrophoneInfo(stream);

        setupMediaRecorder(stream);

        startRecording();
      })
      .catch(error => {
        console.error('Error accessing microphone:', error);
        updateStatusMessage('danger', 'Error accessing your microphone. Please ensure you have given permission to use your microphone.');
        currentState = 'idle';
      });
  });

  function initAudioContext() {
    if (!audioContext) {
      window.AudioContext = window.AudioContext || window.webkitAudioContext;
      audioContext = new AudioContext();

      if (audioContext.state === 'suspended') {
        audioContext.resume();
      }
    }
  }

  function visualize() {
    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    canvasCtx.clearRect(0, 0, visualizer.width, visualizer.height);

    const themeStyles = getComputedStyle(document.documentElement);
    const panelColor = themeStyles.getPropertyValue('--panel-2').trim() || '#ffffff';
    const amberColor = themeStyles.getPropertyValue('--amber').trim() || '#B65C00';

    function draw() {
      if (!microphone) return;

      requestAnimationFrame(draw);

      analyser.getByteTimeDomainData(dataArray);

      const barWidth = barsContainer.clientWidth / amplitudeBars.length;
      const step = Math.floor(bufferLength / amplitudeBars.length);

      for (let i = 0; i < amplitudeBars.length; i++) {
        const dataIndex = i * step;
        const value = Math.abs(dataArray[dataIndex] - 128) / 128;
        const height = Math.max(3, value * visualizer.height);
        amplitudeBars[i].style.height = height + 'px';
      }

      canvasCtx.fillStyle = panelColor;
      canvasCtx.fillRect(0, 0, visualizer.width, visualizer.height);

      canvasCtx.lineWidth = 2;
      canvasCtx.strokeStyle = amberColor;

      canvasCtx.beginPath();

      const sliceWidth = visualizer.width / bufferLength;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const v = dataArray[i] / 128.0;
        const y = v * visualizer.height / 2;

        if (i === 0) {
          canvasCtx.moveTo(x, y);
        } else {
          canvasCtx.lineTo(x, y);
        }

        x += sliceWidth;
      }

      canvasCtx.lineTo(visualizer.width, visualizer.height / 2);
      canvasCtx.stroke();

      let sum = 0;
      for (let i = 0; i < bufferLength; i++) {
        sum += Math.abs(dataArray[i] - 128);
      }
      const average = sum / bufferLength;
      const volume = Math.round((average / 128) * 100);
      volumeEl.textContent = volume + '%';
    }

    draw();
  }

  function setupMediaRecorder(stream) {
    if (typeof MediaRecorder === 'undefined') {
      updateStatusMessage('warning', 'Your browser does not support MediaRecorder. Audio recording and playback may not work.');
      return;
    }

    let mimeType = 'audio/webm';

    if (MediaRecorder.isTypeSupported('audio/webm')) {
      mimeType = 'audio/webm';
    } else if (MediaRecorder.isTypeSupported('audio/mp4')) {
      mimeType = 'audio/mp4';
    } else if (MediaRecorder.isTypeSupported('audio/ogg')) {
      mimeType = 'audio/ogg';
    }

    try {
      mediaRecorder = new MediaRecorder(stream, {mimeType});
    } catch (e) {
      console.warn('Specified MIME type not supported, using default:', e);
      mediaRecorder = new MediaRecorder(stream);
    }

    mediaRecorder.ondataavailable = function (event) {
      if (event.data.size > 0) {
        audioChunks.push(event.data);
      }
    };

    mediaRecorder.onstop = function () {
      finishRecording();
    };

    mediaRecorder.onerror = function (event) {
      console.error('MediaRecorder error:', event);
      updateStatusMessage('danger', 'An error occurred during recording. Please try again.');
    };
  }

  function startRecording() {
    audioChunks = [];
    playButton.disabled = true;
    pauseButton.classList.add('d-none');
    audioPlayerContainer.classList.add('d-none');
    recordingStartTime = Date.now();
    recordingStopped = false;

    if (audioContext && audioContext.state === 'suspended') {
      audioContext.resume();
    }

    try {
      mediaRecorder.start(100);
    } catch (e) {
      console.error('Error starting MediaRecorder:', e);
      updateStatusMessage('danger', 'Failed to start recording. Please refresh and try again.');
      return;
    }

    recordingTimer = setInterval(function () {
      const elapsedTime = Date.now() - recordingStartTime;
      const progress = Math.min(100, (elapsedTime / recordingDuration) * 100);
      recordingProgress.style.width = progress + '%';

      if (currentState === 'recording' && !recordingStopped) {
        const progressLabel = Math.floor(progress);
        updateStatusMessage('recording', `<strong>${progressLabel}.0% Recording in progress: </strong> Testing your microphone and recording your voice.`);
      }

      if (progress >= 100) {
        clearInterval(recordingTimer);
        stopRecording();
      }
    }, 50);
  }

  function stopRecording() {
    if (mediaRecorder && mediaRecorder.state === 'recording') {
      try {
        mediaRecorder.stop();
        recordingStopped = true;
      } catch (e) {
        console.error('Error stopping MediaRecorder:', e);
      }
    }

    if (recordingTimer) {
      clearInterval(recordingTimer);
    }
  }

  function finishRecording() {
    if (audioChunks.length === 0) {
      updateStatusMessage('warning', 'No audio was recorded. Please try again and make sure your microphone is working.');
      return;
    }

    try {
      let mimeType = 'audio/webm';
      if (MediaRecorder.isTypeSupported('audio/webm')) {
        mimeType = 'audio/webm';
      } else if (MediaRecorder.isTypeSupported('audio/mp4')) {
        mimeType = 'audio/mp4';
      } else if (MediaRecorder.isTypeSupported('audio/ogg')) {
        mimeType = 'audio/ogg';
      }

      audioBlob = new Blob(audioChunks, {type: mimeType});
      audioUrl = URL.createObjectURL(audioBlob);

      audioPlayer.src = audioUrl;
      audioPlayerContainer.classList.remove('d-none');

      if (audioElement) {
        audioElement.remove();
      }

      audioElement = document.createElement('audio');
      audioElement.src = audioUrl;

      playButton.disabled = false;
      restartButton.classList.remove('d-none');
      shareButton.classList.remove('d-none');

      currentState = 'complete';
      updateStatusMessage('success', 'Recording complete! Your microphone is working properly. You can now play back your recording or test again.');

      audioPlayer.onplay = function () {
        playButton.classList.add('d-none');
        pauseButton.classList.remove('d-none');
      };

      audioPlayer.onpause = function () {
        pauseButton.classList.add('d-none');
        playButton.classList.remove('d-none');
      };

      audioPlayer.onended = function () {
        pauseButton.classList.add('d-none');
        playButton.classList.remove('d-none');
      };
    } catch (e) {
      console.error('Error creating audio blob:', e);
      updateStatusMessage('danger', 'An error occurred processing the recording. Please try again.');
    }
  }

  function resetUI() {
    testButton.innerHTML = '<i class="bi bi-mic-fill me-2"></i>Test my mic';
    recordingControls.classList.add('d-none');
    audioPlayerContainer.classList.add('d-none');
    resetMicInfo();
    currentState = 'idle';
    updateStatusMessage('info', 'Press "Test my mic" to begin testing your microphone.');
    shareButton.classList.add('d-none');
    restartButton.classList.add('d-none');

    micSelect.innerHTML = '<option value="">Click "Test my mic" to detect microphones</option>';
    micSelect.disabled = true;
    devicesEnumerated = false;

    if (audioUrl) {
      URL.revokeObjectURL(audioUrl);
      audioUrl = null;
    }
  }

  function stopMicrophone() {
    if (microphone) {
      microphone.disconnect();
      microphone = null;
    }

    if (audioContext) {
      if (audioContext.state === 'running') {
        audioContext.suspend();
      }
    }

    if (audioStream) {
      audioStream.getTracks().forEach(track => track.stop());
      audioStream = null;
    }

    if (mediaRecorder && mediaRecorder.state !== 'inactive') {
      try {
        mediaRecorder.stop();
      } catch (e) {
        console.error('Error stopping MediaRecorder:', e);
      }
    }

    if (recordingTimer) {
      clearInterval(recordingTimer);
    }

    canvasCtx.clearRect(0, 0, visualizer.width, visualizer.height);

    for (let i = 0; i < amplitudeBars.length; i++) {
      amplitudeBars[i].style.height = '0px';
    }
  }

  function displayMicrophoneInfo(stream) {
    const track = stream.getAudioTracks()[0];
    const settings = track.getSettings();

    micNameEl.textContent = track.label || 'Unknown microphone';
    gainControlEl.textContent = settings.autoGainControl ? 'Yes' : 'No';
    channelsEl.textContent = settings.channelCount || '1';
    echoCancellationEl.textContent = settings.echoCancellation ? 'Yes' : 'No';
    latencyEl.textContent = settings.latency ? settings.latency + 'ms' : 'Unknown';
    noiseSuppressionEl.textContent = settings.noiseSuppression ? 'Yes' : 'No';
    sampleRateEl.textContent = settings.sampleRate ? settings.sampleRate + 'Hz' : 'Unknown';
    sampleSizeEl.textContent = settings.sampleSize ? settings.sampleSize + 'bits' : 'Unknown';

    let qualityScore = 0;

    if (settings.channelCount && settings.channelCount >= 2) qualityScore += 1;
    if (settings.sampleRate && settings.sampleRate >= 44100) qualityScore += 1;
    if (settings.sampleSize && settings.sampleSize >= 24) qualityScore += 1;
    if (settings.autoGainControl) qualityScore += 0.5;
    if (settings.echoCancellation) qualityScore += 0.5;
    if (settings.noiseSuppression) qualityScore += 0.5;
    if (settings.latency && settings.latency < 50) qualityScore += 0.5;

    let qualityRating;
    let qualityClass;

    if (qualityScore >= 4) {
      qualityRating = 'Excellent';
      qualityClass = 'quality-excellent';
    } else if (qualityScore >= 3) {
      qualityRating = 'Very Good';
      qualityClass = 'quality-verygood';
    } else if (qualityScore >= 2) {
      qualityRating = 'Good';
      qualityClass = 'quality-good';
    } else if (qualityScore >= 1) {
      qualityRating = 'Fair';
      qualityClass = 'quality-fair';
    } else {
      qualityRating = 'Poor';
      qualityClass = 'quality-poor';
    }

    qualityRatingEl.textContent = qualityRating;
    qualityRatingEl.className = 'quality-indicator ' + qualityClass;
  }

  function resetMicInfo() {
    micNameEl.textContent = 'Not selected';
    gainControlEl.textContent = '—';
    channelsEl.textContent = '—';
    echoCancellationEl.textContent = '—';
    latencyEl.textContent = '—';
    noiseSuppressionEl.textContent = '—';
    sampleRateEl.textContent = '—';
    sampleSizeEl.textContent = '—';
    volumeEl.textContent = '—';
    qualityRatingEl.textContent = '—';
    qualityRatingEl.className = 'quality-indicator quality-unknown';
  }

  playButton.addEventListener('click', function () {
    if (audioPlayer && audioPlayer.src) {
      try {
        audioPlayer.play()
          .then(() => {
            playButton.classList.add('d-none');
            pauseButton.classList.remove('d-none');
          })
          .catch(e => {
            console.error('Error playing audio:', e);
            if (audioElement) {
              audioElement.play();
              playButton.classList.add('d-none');
              pauseButton.classList.remove('d-none');
            }
          });
      } catch (e) {
        console.error('Error playing audio:', e);
        updateStatusMessage('warning', 'Error playing audio. This might be a browser limitation.');
      }
    }
  });

  pauseButton.addEventListener('click', function () {
    if (audioPlayer && !audioPlayer.paused) {
      audioPlayer.pause();
    }

    if (audioElement && !audioElement.paused) {
      audioElement.pause();
    }

    pauseButton.classList.add('d-none');
    playButton.classList.remove('d-none');
  });

  stopRecordingButton.addEventListener('click', function () {
    if (currentState === 'recording' && !recordingStopped) {
      stopRecording();
    }
  });

  restartButton.addEventListener('click', function () {
    if (audioStream && currentState === 'complete') {
      startRecording();
      currentState = 'recording';
      updateStatusMessage('recording', '<strong>Recording in progress: </strong> Testing your microphone and recording your voice.');
      restartButton.classList.add('d-none');
      shareButton.classList.add('d-none');
    }
  });

  shareButton.addEventListener('click', function () {
    reviewForm.style.display = 'block';
    this.disabled = true;
  });

  addReviewBtn.addEventListener('click', function () {
    reviewForm.style.display = 'block';
  });

  cancelReviewBtn.addEventListener('click', function () {
    reviewForm.style.display = 'none';
    shareButton.disabled = false;
  });

  submitReviewBtn.addEventListener('click', function () {
    const reviewText = document.getElementById('review-text').value;
    const reviewerName = document.getElementById('reviewer-name').value;

    if (reviewText && reviewerName) {
      const testimonialDiv = document.createElement('div');
      testimonialDiv.className = 'testimonial';

      const reviewPara = document.createElement('p');
      reviewPara.className = 'mb-0';
      reviewPara.textContent = `"${reviewText}"`;

      const nameSmall = document.createElement('small');
      nameSmall.className = 'text-muted';
      nameSmall.textContent = `— ${reviewerName}`;

      testimonialDiv.appendChild(reviewPara);
      testimonialDiv.appendChild(nameSmall);

      const testimonialsContainer = document.getElementById('testimonials-list');
      testimonialsContainer.insertBefore(testimonialDiv, testimonialsContainer.firstChild);

      document.getElementById('review-text').value = '';
      document.getElementById('reviewer-name').value = '';
      reviewForm.style.display = 'none';
      shareButton.disabled = false;

      alert('Thank you for your review!');
    } else {
      alert('Please fill in both fields');
    }
  });

  function resizeCanvas() {
    visualizer.width = visualizer.clientWidth;
    visualizer.height = visualizer.clientHeight;
  }

  window.addEventListener('resize', resizeCanvas);
  resizeCanvas();

  document.addEventListener('touchstart', function () {
    if (audioContext && audioContext.state === 'suspended') {
      audioContext.resume();
    }
  }, {once: true});

  document.addEventListener('touchend', function () {
    if (audioPlayer && audioPlayer.src && audioPlayer.paused) {
      audioPlayer.play().catch(e => console.log('Play attempted but not allowed yet'));
    }
  }, {once: true});
});

extra_style:
.text-success{color:var(--success);}
.text-primary{color:var(--amber);}
.text-info{color:var(--ink-2);}
.text-warning{color:var(--amber);}
.text-danger{color:var(--red);}

#devices-container{display:flex;flex-wrap:wrap;gap:1rem;}
#devices-container>.col-md-4{flex:1 1 240px;}
#devices-container>.col-12{flex:1 1 100%;}

.card{border:1px solid var(--border);border-radius:4px;background:var(--panel);}
.card-body{padding:1rem;}
.card-title{font-family:'JetBrains Mono',monospace;font-size:13px;font-weight:600;color:var(--ink);margin:0 0 .4rem;display:flex;align-items:center;gap:.45rem;}
.card-text{font-size:11.5px;margin:0 0 .7rem;}
.device-card{cursor:pointer;transition:transform .15s ease;}
.device-card:hover{transform:translateY(-2px);}
.device-card.selected{border-color:var(--amber);border-width:2px;}

.status-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--ink-3);margin-right:.4rem;}
.status-dot.connected{background:var(--success);}
.status-dot.default{background:var(--amber);}
.status-dot.disconnected{background:var(--red);}

.btn-outline-primary{display:inline-flex;align-items:center;justify-content:center;font-size:11.5px;font-weight:600;padding:.4rem .8rem;border-radius:4px;border:1px solid var(--amber);background:transparent;color:var(--amber);cursor:pointer;font-family:'IBM Plex Sans',sans-serif;}
.btn-outline-primary:hover{background:var(--amber-dim);}

.no-microphones{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:2rem;text-align:center;background:var(--panel-2);border-radius:4px;border:1px solid var(--border);}
.no-microphones i{font-size:3rem;margin-bottom:1rem;color:var(--ink-3);}

#spectrogram-container{position:relative;height:200px;margin-top:1rem;border:1px solid var(--border);border-radius:4px;overflow:hidden;background:var(--panel-2);}
#spectrogram-container canvas{width:100%;height:100%;}

script:
document.addEventListener('DOMContentLoaded', function () {
  // DOM Elements
  const browserAlert = document.getElementById('browser-alert');
  const browserMessage = document.getElementById('browser-message');
  const devicesContainer = document.getElementById('devices-container');
  const deviceDetails = document.getElementById('device-details');
  const refreshButton = document.getElementById('refresh-button');
  const testButton = document.getElementById('test-button');
  const stopButton = document.getElementById('stop-button');
  const spectrogram = document.getElementById('spectrogram');

  // Variables for audio handling
  let audioContext;
  let analyser;
  let microphone;
  let spectrogramCtx;
  let activeDeviceId = null;
  let audioStream = null;
  let animationFrame = null;

  // Initialize the canvas
  spectrogramCtx = spectrogram.getContext('2d');

  // Function to resize the canvas
  function resizeCanvas() {
    spectrogram.width = spectrogram.offsetWidth;
    spectrogram.height = spectrogram.offsetHeight;
  }

  // Call resize initially and on window resize
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  // Check browser compatibility for media devices
  if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) {
    browserMessage.innerHTML = `
                  <i class="bi bi-exclamation-triangle-fill me-2 text-danger"></i>
                  Your browser doesn't support the required features to detect audio devices. Please use a modern browser like Chrome, Firefox, or Edge.
              `;
    browserAlert.classList.remove('alert-info');
    browserAlert.classList.add('alert-danger');
    return;
  }

  // Function to fetch and display all audio input devices
  function getAudioDevices() {
    browserMessage.innerHTML = `
                  <i class="bi bi-info-circle-fill me-2"></i>
                  Detecting your microphones. Please wait...
              `;

    // Clear existing devices
    devicesContainer.innerHTML = '';

    // Flag to check if we need permission first
    let needsPermission = true;

    // First, enumerate to check if we need permission
    navigator.mediaDevices.enumerateDevices()
      .then(devices => {
        const mics = devices.filter(device => device.kind === 'audioinput');

        // If we already have labels, we don't need to request permission
        if (mics.length > 0 && mics.some(mic => mic.label)) {
          needsPermission = false;
          displayDevices(mics);
        } else if (mics.length === 0) {
          // No microphones found
          displayNoMicrophones();
          needsPermission = false;
        }

        // If we need permission, request it
        if (needsPermission) {
          browserMessage.innerHTML = `
                              <i class="bi bi-info-circle-fill me-2"></i>
                              Please allow access to your microphone when prompted.
                          `;

          return navigator.mediaDevices.getUserMedia({audio: true})
            .then(stream => {
              // Stop the stream immediately, we just needed permission
              stream.getTracks().forEach(track => track.stop());

              // Now enumerate devices again with permission
              return navigator.mediaDevices.enumerateDevices();
            })
            .then(devices => {
              const mics = devices.filter(device => device.kind === 'audioinput');
              displayDevices(mics);
            });
        }
      })
      .catch(error => {
        console.error('Error enumerating devices:', error);
        browserMessage.innerHTML = `
                          <i class="bi bi-exclamation-triangle-fill me-2 text-danger"></i>
                          Error accessing your audio devices: ${error.message}. Please ensure you've granted permission to access your microphone.
                      `;
        browserAlert.classList.remove('alert-info');
        browserAlert.classList.add('alert-danger');
      });
  }

  // Function to display no microphones message
  function displayNoMicrophones() {
    devicesContainer.innerHTML = `
                  <div class="col-12">
                      <div class="no-microphones">
                          <i class="bi bi-mic-mute"></i>
                          <h4>No Microphones Detected</h4>
                          <p>We couldn't find any microphones connected to your device. Please connect a microphone and click the Refresh button.</p>
                      </div>
                  </div>
              `;

    browserMessage.innerHTML = `
                  <i class="bi bi-exclamation-triangle-fill me-2 text-warning"></i>
                  No microphones detected. Please connect a microphone and refresh.
              `;
    browserAlert.classList.remove('alert-info');
    browserAlert.classList.add('alert-warning');

    // Hide device details
    deviceDetails.classList.add('d-none');
  }

  // Function to display found devices
  function displayDevices(mics) {
    if (mics.length === 0) {
      displayNoMicrophones();
      return;
    }

    browserMessage.innerHTML = `
                  <i class="bi bi-check-circle-fill me-2 text-success"></i>
                  Found ${mics.length} microphone${mics.length > 1 ? 's' : ''}. Click on a microphone to view detailed information.
              `;
    browserAlert.classList.remove('alert-info');
    browserAlert.classList.add('alert-success');

    // Create card for each device
    mics.forEach((device, index) => {
      const deviceCard = document.createElement('div');
      deviceCard.className = 'col-md-4';
      deviceCard.innerHTML = `
                      <div class="card device-card" data-device-id="${device.deviceId}">
                          <div class="card-body">
                              <h5 class="card-title">
                                  <span class="status-dot connected"></span>
                                  ${device.label || `Microphone ${index + 1}`}
                              </h5>
                              <p class="card-text text-muted">
                                  ${device.deviceId.substring(0, 8)}...
                              </p>
                              <button class="btn btn-outline-primary btn-sm">
                                  <i class="bi bi-info-circle me-1"></i>View Details
                              </button>
                          </div>
                      </div>
                  `;
      devicesContainer.appendChild(deviceCard);

      // Add click event to the card
      const card = deviceCard.querySelector('.device-card');
      card.addEventListener('click', () => {
        // Remove selected class from all cards
        document.querySelectorAll('.device-card').forEach(c => {
          c.classList.remove('selected');
        });

        // Add selected class to this card
        card.classList.add('selected');

        // Show device details
        showDeviceDetails(device);
      });
    });
  }

  // Function to show device details
  function showDeviceDetails(device) {
    // Set active device ID
    activeDeviceId = device.deviceId;

    // Show the details card
    deviceDetails.classList.remove('d-none');

    // Update the device name
    document.getElementById('selected-device-name').textContent = device.label || 'Unknown Microphone';

    // Update basic info
    document.getElementById('device-id').textContent = device.deviceId;
    document.getElementById('group-id').textContent = device.groupId;
    document.getElementById('is-default').textContent = 'Checking...';
    document.getElementById('device-status').innerHTML = '<span class="status-dot connected"></span> Connected';

    // Get detailed info about the device
    getDeviceDetails(device.deviceId);
  }

  // Function to get detailed device information
  function getDeviceDetails(deviceId) {
    // Reset all fields first
    document.getElementById('sample-rate').textContent = '—';
    document.getElementById('sample-size').textContent = '—';
    document.getElementById('channel-count').textContent = '—';
    document.getElementById('latency').textContent = '—';
    document.getElementById('auto-gain').textContent = '—';
    document.getElementById('echo-cancellation').textContent = '—';
    document.getElementById('noise-suppression').textContent = '—';
    document.getElementById('volume').textContent = '—';
    document.getElementById('quality-rating').textContent = '—';

    // Request access to the specific device
    navigator.mediaDevices.getUserMedia({
      audio: {
        deviceId: {exact: deviceId}
      }
    })
      .then(stream => {
        // Store the stream so we can stop it later
        if (audioStream) {
          audioStream.getTracks().forEach(track => track.stop());
        }
        audioStream = stream;

        // Get the audio track
        const track = stream.getAudioTracks()[0];

        // Get capabilities and settings
        const capabilities = track.getCapabilities ? track.getCapabilities() : {};
        const settings = track.getSettings ? track.getSettings() : {};

        // Update UI with settings
        if (settings.sampleRate) {
          document.getElementById('sample-rate').textContent = settings.sampleRate + ' Hz';
        }

        if (settings.sampleSize) {
          document.getElementById('sample-size').textContent = settings.sampleSize + ' bits';
        }

        if (settings.channelCount) {
          document.getElementById('channel-count').textContent = settings.channelCount + ' channel' + (settings.channelCount > 1 ? 's' : '');
        }

        if (settings.latency) {
          document.getElementById('latency').textContent = settings.latency + ' ms';
        }

        if (settings.autoGainControl !== undefined) {
          document.getElementById('auto-gain').textContent = settings.autoGainControl ? 'Enabled' : 'Disabled';
        }

        if (settings.echoCancellation !== undefined) {
          document.getElementById('echo-cancellation').textContent = settings.echoCancellation ? 'Enabled' : 'Disabled';
        }

        if (settings.noiseSuppression !== undefined) {
          document.getElementById('noise-suppression').textContent = settings.noiseSuppression ? 'Enabled' : 'Disabled';
        }

        // Check if this is the default device
        navigator.mediaDevices.enumerateDevices()
          .then(devices => {
            const audioInputs = devices.filter(d => d.kind === 'audioinput');

            if (audioInputs.length > 0 && audioInputs[0].deviceId === deviceId) {
              document.getElementById('is-default').innerHTML = '<span class="status-dot default"></span> Default Device';
            } else {
              document.getElementById('is-default').innerHTML = 'Not Default';
            }
          });

        // Calculate quality rating
        let qualityScore = 0;
        if (settings.channelCount && settings.channelCount >= 2) qualityScore += 1;
        if (settings.sampleRate && settings.sampleRate >= 44100) qualityScore += 1;
        if (settings.sampleSize && settings.sampleSize >= 24) qualityScore += 1;
        if (settings.autoGainControl) qualityScore += 0.5;
        if (settings.echoCancellation) qualityScore += 0.5;
        if (settings.noiseSuppression) qualityScore += 0.5;
        if (settings.latency && settings.latency < 50) qualityScore += 0.5;

        let qualityRating;
        let qualityClass;

        if (qualityScore >= 4) {
          qualityRating = 'Excellent';
          qualityClass = 'text-success';
        } else if (qualityScore >= 3) {
          qualityRating = 'Very Good';
          qualityClass = 'text-primary';
        } else if (qualityScore >= 2) {
          qualityRating = 'Good';
          qualityClass = 'text-info';
        } else if (qualityScore >= 1) {
          qualityRating = 'Fair';
          qualityClass = 'text-warning';
        } else {
          qualityRating = 'Basic';
          qualityClass = 'text-danger';
        }

        document.getElementById('quality-rating').innerHTML = `<span class="${qualityClass}">${qualityRating}</span>`;

        // Stop the stream after getting info
        stream.getTracks().forEach(track => track.stop());
        audioStream = null;
      })
      .catch(error => {
        console.error('Error getting device details:', error);
        document.getElementById('device-status').innerHTML = '<span class="status-dot disconnected"></span> Error: ' + error.message;
      });
  }

  // Function to test the microphone
  function testMicrophone() {
    if (!activeDeviceId) {
      alert('Please select a microphone first');
      return;
    }

    // Swap buttons
    testButton.classList.add('d-none');
    stopButton.classList.remove('d-none');

    // Initialize audio context (wait until user interaction)
    if (!audioContext) {
      window.AudioContext = window.AudioContext || window.webkitAudioContext;
      audioContext = new AudioContext();
    }

    // Request the selected device
    navigator.mediaDevices.getUserMedia({
      audio: {
        deviceId: {exact: activeDeviceId}
      }
    })
      .then(stream => {
        // Store the stream
        audioStream = stream;

        // Create analyzer
        analyser = audioContext.createAnalyser();
        analyser.fftSize = 2048;

        // Connect microphone to analyser
        microphone = audioContext.createMediaStreamSource(stream);
        microphone.connect(analyser);

        // Start visualization
        visualize();

        // Start monitoring volume
        startVolumeMonitoring();
      })
      .catch(error => {
        console.error('Error accessing microphone:', error);
        alert('Error accessing microphone: ' + error.message);

        // Reset buttons
        stopButton.classList.add('d-none');
        testButton.classList.remove('d-none');
      });
  }

  // Function to visualize audio
  function visualize() {
    if (!analyser) return;

    // Get the canvas dimensions
    const width = spectrogram.width;
    const height = spectrogram.height;

    // Set up the analyzer
    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    // Clear the canvas
    spectrogramCtx.clearRect(0, 0, width, height);
    spectrogramCtx.fillStyle = 'rgb(248, 249, 250)';
    spectrogramCtx.fillRect(0, 0, width, height);

    function draw() {
      if (!analyser) {
        return;
      }

      // Request next frame
      animationFrame = requestAnimationFrame(draw);

      // Get frequency data
      analyser.getByteFrequencyData(dataArray);

      // Clear canvas
      spectrogramCtx.clearRect(0, 0, width, height);
      spectrogramCtx.fillStyle = 'rgb(248, 249, 250)';
      spectrogramCtx.fillRect(0, 0, width, height);

      // Draw frequency bars
      const barWidth = width / bufferLength * 2.5;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const barHeight = dataArray[i] / 255 * height;

        // Create gradient
        const gradient = spectrogramCtx.createLinearGradient(0, height, 0, height - barHeight);
        gradient.addColorStop(0, 'rgb(13, 110, 253, 0.8)');
        gradient.addColorStop(1, 'rgb(13, 110, 253, 0.2)');

        spectrogramCtx.fillStyle = gradient;
        spectrogramCtx.fillRect(x, height - barHeight, barWidth, barHeight);

        x += barWidth + 1;

        // Only draw a subset of bars for performance
        if (i > bufferLength / 4) break;
      }
    }

    draw();
  }

  // Function to monitor volume
  function startVolumeMonitoring() {
    if (!analyser) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    function checkVolume() {
      if (!analyser) {
        return;
      }

      // Get time domain data
      analyser.getByteTimeDomainData(dataArray);

      // Calculate volume
      let sum = 0;
      for (let i = 0; i < bufferLength; i++) {
        sum += Math.abs(dataArray[i] - 128);
      }

      const average = sum / bufferLength;
      const volume = Math.round((average / 128) * 100);

      // Update UI
      document.getElementById('volume').textContent = volume + '%';

      // Call again
      setTimeout(checkVolume, 100);
    }

    checkVolume();
  }

  // Function to stop microphone test
  function stopMicTest() {
    // Cancel animation frame
    if (animationFrame) {
      cancelAnimationFrame(animationFrame);
      animationFrame = null;
    }

    // Stop the audio stream
    if (audioStream) {
      audioStream.getTracks().forEach(track => track.stop());
      audioStream = null;
    }

    // Clean up audio nodes
    if (microphone) {
      microphone.disconnect();
      microphone = null;
    }

    analyser = null;

    // Reset buttons
    stopButton.classList.add('d-none');
    testButton.classList.remove('d-none');

    // Clear canvas
    spectrogramCtx.clearRect(0, 0, spectrogram.width, spectrogram.height);
    spectrogramCtx.fillStyle = 'rgb(248, 249, 250)';
    spectrogramCtx.fillRect(0, 0, spectrogram.width, spectrogram.height);

    // Reset volume display
    document.getElementById('volume').textContent = '—';
  }

  // Event listeners
  refreshButton.addEventListener('click', getAudioDevices);
  testButton.addEventListener('click', testMicrophone);
  stopButton.addEventListener('click', stopMicTest);

  // Initialize
  getAudioDevices();
});

document.addEventListener('DOMContentLoaded', function() {
  const recordBtn = document.getElementById('record-btn');
  const stopBtn = document.getElementById('stop-btn');
  const micSelect = document.getElementById('mic-select');
  const recordingTime = document.getElementById('recording-time');
  const statusMessage = document.getElementById('status-message');
  const statusAlert = document.getElementById('status-alert');
  const playbackSection = document.getElementById('playback-section');
  const audioPlayback = document.getElementById('audio-playback');
  const downloadMp3Btn = document.getElementById('download-mp3-btn');
  const downloadWavBtn = document.getElementById('download-wav-btn');
  const newRecordingBtn = document.getElementById('new-recording-btn');
  const waveformCanvas = document.getElementById('waveform');
  const waveformCtx = waveformCanvas.getContext('2d');

  let mediaRecorder = null;
  let audioChunks = [];
  let audioBlob = null;
  let audioStream = null;
  let audioContext = null;
  let analyser = null;
  let animationId = null;
  let startTime = null;
  let timerInterval = null;

  // Resize canvas
  function resizeCanvas() {
    waveformCanvas.width = waveformCanvas.offsetWidth;
    waveformCanvas.height = waveformCanvas.offsetHeight;
  }
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  // Get audio devices
  async function getAudioDevices() {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach(track => track.stop());

      const devices = await navigator.mediaDevices.enumerateDevices();
      const audioInputs = devices.filter(d => d.kind === 'audioinput');

      micSelect.innerHTML = '';
      audioInputs.forEach((device, index) => {
        const option = document.createElement('option');
        option.value = device.deviceId;
        option.text = device.label || `Microphone ${index + 1}`;
        micSelect.appendChild(option);
      });
      micSelect.disabled = false;
    } catch (error) {
      updateStatus('danger', 'Microphone access denied. Please allow microphone permissions.');
    }
  }

  // Update status
  function updateStatus(type, message) {
    statusAlert.className = `alert alert-${type}`;
    statusMessage.innerHTML = message;
  }

  // Format time
  function formatTime(seconds) {
    const mins = Math.floor(seconds / 60).toString().padStart(2, '0');
    const secs = Math.floor(seconds % 60).toString().padStart(2, '0');
    return `${mins}:${secs}`;
  }

  // Draw waveform
  function drawWaveform() {
    if (!analyser) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    analyser.getByteTimeDomainData(dataArray);

    waveformCtx.fillStyle = '#f8f9fa';
    waveformCtx.fillRect(0, 0, waveformCanvas.width, waveformCanvas.height);

    waveformCtx.lineWidth = 2;
    waveformCtx.strokeStyle = '#0055FF';
    waveformCtx.beginPath();

    const sliceWidth = waveformCanvas.width / bufferLength;
    let x = 0;

    for (let i = 0; i < bufferLength; i++) {
      const v = dataArray[i] / 128.0;
      const y = v * waveformCanvas.height / 2;

      if (i === 0) {
        waveformCtx.moveTo(x, y);
      } else {
        waveformCtx.lineTo(x, y);
      }
      x += sliceWidth;
    }

    waveformCtx.lineTo(waveformCanvas.width, waveformCanvas.height / 2);
    waveformCtx.stroke();

    animationId = requestAnimationFrame(drawWaveform);
  }

  // Start recording
  async function startRecording() {
    try {
      const deviceId = micSelect.value;
      const constraints = {
        audio: deviceId ? { deviceId: { exact: deviceId } } : true
      };

      audioStream = await navigator.mediaDevices.getUserMedia(constraints);

      // Setup audio context and analyser
      audioContext = new (window.AudioContext || window.webkitAudioContext)();
      analyser = audioContext.createAnalyser();
      const source = audioContext.createMediaStreamSource(audioStream);
      source.connect(analyser);
      analyser.fftSize = 2048;

      // Start visualization
      drawWaveform();

      // Setup media recorder
      mediaRecorder = new MediaRecorder(audioStream);
      audioChunks = [];

      mediaRecorder.ondataavailable = (event) => {
        audioChunks.push(event.data);
      };

      mediaRecorder.onstop = () => {
        audioBlob = new Blob(audioChunks, { type: 'audio/wav' });
        const audioUrl = URL.createObjectURL(audioBlob);
        audioPlayback.src = audioUrl;
        playbackSection.classList.remove('d-none');
        updateStatus('success', 'Recording complete! Preview your recording below.');
      };

      mediaRecorder.start();
      startTime = Date.now();

      // Start timer
      timerInterval = setInterval(() => {
        const elapsed = (Date.now() - startTime) / 1000;
        recordingTime.textContent = formatTime(elapsed);
      }, 100);

      recordBtn.disabled = true;
      stopBtn.disabled = false;
      micSelect.disabled = true;
      updateStatus('danger', '<span class="recording-indicator d-inline-block me-2"></span>Recording in progress...');
    } catch (error) {
      updateStatus('danger', 'Error starting recording: ' + error.message);
    }
  }

  // Stop recording
  function stopRecording() {
    if (mediaRecorder && mediaRecorder.state !== 'inactive') {
      mediaRecorder.stop();
    }

    if (audioStream) {
      audioStream.getTracks().forEach(track => track.stop());
    }

    if (animationId) {
      cancelAnimationFrame(animationId);
    }

    if (timerInterval) {
      clearInterval(timerInterval);
    }

    recordBtn.disabled = false;
    stopBtn.disabled = true;
    micSelect.disabled = false;
  }

  // Download as WAV
  function downloadWav() {
    if (!audioBlob) return;
    const url = URL.createObjectURL(audioBlob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `recording_${Date.now()}.wav`;
    a.click();
    URL.revokeObjectURL(url);
  }

  // Download as MP3 (using WAV for now - MP3 encoding requires additional library)
  function downloadMp3() {
    // For simplicity, downloading as WAV (MP3 encoding would require lamejs or similar)
    if (!audioBlob) return;
    const url = URL.createObjectURL(audioBlob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `recording_${Date.now()}.wav`;
    a.click();
    URL.revokeObjectURL(url);
    updateStatus('info', 'Downloaded as WAV format. MP3 conversion requires additional processing.');
  }

  // New recording
  function newRecording() {
    playbackSection.classList.add('d-none');
    recordingTime.textContent = '00:00';
    audioPlayback.src = '';
    audioBlob = null;
    audioChunks = [];
    updateStatus('info', 'Click the record button to start a new recording.');

    // Clear canvas
    waveformCtx.fillStyle = '#f8f9fa';
    waveformCtx.fillRect(0, 0, waveformCanvas.width, waveformCanvas.height);
  }

  // Event listeners
  recordBtn.addEventListener('click', startRecording);
  stopBtn.addEventListener('click', stopRecording);
  downloadWavBtn.addEventListener('click', downloadWav);
  downloadMp3Btn.addEventListener('click', downloadMp3);
  newRecordingBtn.addEventListener('click', newRecording);

  // Initialize
  getAudioDevices();
});

