script:
document.addEventListener('DOMContentLoaded', function() {
  const startBtn = document.getElementById('start-btn');
  const micSelect = document.getElementById('mic-select');
  const spectrumCanvas = document.getElementById('spectrum-canvas');
  const spectrumCtx = spectrumCanvas.getContext('2d');
  const noiseIndicator = document.getElementById('noise-indicator');
  const currentLevel = document.getElementById('current-level');
  const avgLevel = document.getElementById('avg-level');
  const environmentRating = document.getElementById('environment-rating');
  const recommendations = document.getElementById('recommendations');
  const statusMessage = document.getElementById('status-message');
  const statusAlert = document.getElementById('status-alert');

  const lowFreq = document.getElementById('low-freq');
  const midLowFreq = document.getElementById('mid-low-freq');
  const midHighFreq = document.getElementById('mid-high-freq');
  const highFreq = document.getElementById('high-freq');

  let audioContext = null;
  let analyser = null;
  let audioStream = null;
  let isRunning = false;
  let animationId = null;
  let readings = [];

  // Resize canvas
  function resizeCanvas() {
    spectrumCanvas.width = spectrumCanvas.parentElement.offsetWidth;
    spectrumCanvas.height = spectrumCanvas.parentElement.offsetHeight;
  }
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  // Get audio devices
  async function getAudioDevices() {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach(track => track.stop());

      const devices = await navigator.mediaDevices.enumerateDevices();
      const audioInputs = devices.filter(d => d.kind === 'audioinput');

      micSelect.innerHTML = '';
      audioInputs.forEach((device, index) => {
        const option = document.createElement('option');
        option.value = device.deviceId;
        option.text = device.label || `Microphone ${index + 1}`;
        micSelect.appendChild(option);
      });
      micSelect.disabled = false;
    } catch (error) {
      updateStatus('danger', 'Microphone access denied.');
    }
  }

  function updateStatus(type, message) {
    statusAlert.className = `alert alert-${type}`;
    statusMessage.innerHTML = message;
  }

  // Draw spectrum
  function drawSpectrum() {
    if (!analyser || !isRunning) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    analyser.getByteFrequencyData(dataArray);

    spectrumCtx.fillStyle = '#1a1a2e';
    spectrumCtx.fillRect(0, 0, spectrumCanvas.width, spectrumCanvas.height);

    const barWidth = (spectrumCanvas.width / bufferLength) * 2.5;
    let x = 0;

    for (let i = 0; i < bufferLength; i++) {
      const barHeight = (dataArray[i] / 255) * spectrumCanvas.height;

      // Color gradient based on frequency
      const hue = (i / bufferLength) * 120 + 200; // Blue to green
      spectrumCtx.fillStyle = `hsl(${hue}, 70%, 50%)`;
      spectrumCtx.fillRect(x, spectrumCanvas.height - barHeight, barWidth, barHeight);

      x += barWidth + 1;
    }

    // Calculate levels
    const calculateBandLevel = (start, end) => {
      let sum = 0;
      const startIdx = Math.floor(start / 22050 * bufferLength);
      const endIdx = Math.floor(end / 22050 * bufferLength);
      for (let i = startIdx; i < endIdx && i < bufferLength; i++) {
        sum += dataArray[i];
      }
      return Math.round(sum / (endIdx - startIdx));
    };

    const low = calculateBandLevel(20, 250);
    const midLow = calculateBandLevel(250, 500);
    const midHigh = calculateBandLevel(500, 2000);
    const high = calculateBandLevel(2000, 20000);

    lowFreq.textContent = low;
    midLowFreq.textContent = midLow;
    midHighFreq.textContent = midHigh;
    highFreq.textContent = high;

    // Overall level
    let sum = 0;
    for (let i = 0; i < bufferLength; i++) {
      sum += dataArray[i];
    }
    const avgValue = sum / bufferLength;
    const db = Math.round((avgValue / 255) * 100);

    currentLevel.textContent = db;
    readings.push(db);
    if (readings.length > 100) readings.shift();

    const avgDb = Math.round(readings.reduce((a, b) => a + b, 0) / readings.length);
    avgLevel.textContent = avgDb;

    // Update noise indicator
    noiseIndicator.style.left = `${Math.min(db, 100)}%`;

    // Environment rating
    let rating, ratingClass;
    if (avgDb < 30) {
      rating = 'Excellent';
      ratingClass = 'bg-success';
    } else if (avgDb < 40) {
      rating = 'Good';
      ratingClass = 'bg-success';
    } else if (avgDb < 50) {
      rating = 'Acceptable';
      ratingClass = 'bg-warning';
    } else if (avgDb < 60) {
      rating = 'Noisy';
      ratingClass = 'bg-warning';
    } else {
      rating = 'Too Loud';
      ratingClass = 'bg-danger';
    }
    environmentRating.innerHTML = `<span class="badge ${ratingClass} quality-badge">${rating}</span>`;

    // Update recommendations
    updateRecommendations(avgDb, low, high);

    animationId = requestAnimationFrame(drawSpectrum);
  }

  function updateRecommendations(avgDb, low, high) {
    let recs = [];

    if (avgDb > 50) {
      recs.push('⚠️ High background noise detected. Consider moving to a quieter location.');
    }
    if (low > 100) {
      recs.push('🔊 High low-frequency noise (possibly HVAC, traffic). Try closing windows or using a high-pass filter.');
    }
    if (high > 80) {
      recs.push('📡 High-frequency noise detected (possibly electrical interference). Check for nearby electronics.');
    }
    if (avgDb < 30) {
      recs.push('✅ Excellent! Your environment is very quiet - ideal for recording.');
    }
    if (avgDb >= 30 && avgDb < 45) {
      recs.push('✅ Good environment for video calls and casual recording.');
    }

    if (recs.length === 0) {
      recs.push('Analysis in progress... Keep monitoring for accurate results.');
    }

    recommendations.innerHTML = recs.map(r => `<p class="mb-2">${r}</p>`).join('');
  }

  // Start analysis
  async function startAnalysis() {
    if (isRunning) {
      stopAnalysis();
      return;
    }

    try {
      const deviceId = micSelect.value;
      const constraints = {
        audio: deviceId ? { deviceId: { exact: deviceId } } : true
      };

      audioStream = await navigator.mediaDevices.getUserMedia(constraints);
      audioContext = new (window.AudioContext || window.webkitAudioContext)();
      analyser = audioContext.createAnalyser();
      const source = audioContext.createMediaStreamSource(audioStream);
      source.connect(analyser);
      analyser.fftSize = 2048;

      isRunning = true;
      readings = [];
      startBtn.innerHTML = '<i class="bi bi-stop-fill me-2"></i>Stop Analysis';
      startBtn.classList.remove('btn-primary');
      startBtn.classList.add('btn-danger');
      micSelect.disabled = true;

      updateStatus('success', 'Analyzing background noise... Stay quiet to measure ambient levels.');
      drawSpectrum();

    } catch (error) {
      updateStatus('danger', 'Error: ' + error.message);
    }
  }

  function stopAnalysis() {
    isRunning = false;

    if (animationId) cancelAnimationFrame(animationId);
    if (audioStream) audioStream.getTracks().forEach(track => track.stop());
    if (audioContext) audioContext.close();

    startBtn.innerHTML = '<i class="bi bi-play-fill me-2"></i>Start Analysis';
    startBtn.classList.remove('btn-danger');
    startBtn.classList.add('btn-primary');
    micSelect.disabled = false;

    updateStatus('info', 'Analysis stopped. Click "Start Analysis" to begin again.');
  }

  // Event listeners
  startBtn.addEventListener('click', startAnalysis);

  // Initialize
  getAudioDevices();
});

document.addEventListener('DOMContentLoaded', function() {
  const micSelect = document.getElementById('mic-select');
  const recordBtn = document.getElementById('record-btn');
  const playBtn = document.getElementById('play-btn');
  const delaySlider = document.getElementById('delay-slider');
  const delayValue = document.getElementById('delay-value');
  const monitorBtn = document.getElementById('monitor-btn');
  const monitorDelay = document.getElementById('monitor-delay');
  const monitorDelayValue = document.getElementById('monitor-delay-value');
  const statusMessage = document.getElementById('status-message');
  const statusAlert = document.getElementById('status-alert');
  const recordingStatus = document.getElementById('recording-status');
  const recordProgress = document.getElementById('record-progress');
  const testResults = document.getElementById('test-results');
  const visualizer = document.getElementById('visualizer');
  const visualizerCtx = visualizer.getContext('2d');

  let audioContext = null;
  let mediaRecorder = null;
  let audioChunks = [];
  let audioBlob = null;
  let audioStream = null;
  let isMonitoring = false;
  let monitorSource = null;
  let delayNode = null;
  let analyser = null;
  let animationId = null;

  // Resize canvas
  function resizeCanvas() {
    visualizer.width = visualizer.parentElement.offsetWidth;
    visualizer.height = visualizer.parentElement.offsetHeight;
  }
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  // Update status
  function updateStatus(type, message) {
    statusAlert.className = `alert alert-${type}`;
    statusMessage.innerHTML = message;
  }

  // Get audio devices
  async function getAudioDevices() {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach(track => track.stop());

      const devices = await navigator.mediaDevices.enumerateDevices();
      const audioInputs = devices.filter(d => d.kind === 'audioinput');

      micSelect.innerHTML = '';
      audioInputs.forEach((device, index) => {
        const option = document.createElement('option');
        option.value = device.deviceId;
        option.text = device.label || `Microphone ${index + 1}`;
        micSelect.appendChild(option);
      });
      micSelect.disabled = false;
    } catch (error) {
      updateStatus('danger', 'Microphone access denied. Please allow microphone permissions.');
    }
  }

  // Draw visualizer
  function drawVisualizer() {
    if (!analyser) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    analyser.getByteTimeDomainData(dataArray);

    visualizerCtx.fillStyle = '#f8f9fa';
    visualizerCtx.fillRect(0, 0, visualizer.width, visualizer.height);

    visualizerCtx.lineWidth = 2;
    visualizerCtx.strokeStyle = '#0055FF';
    visualizerCtx.beginPath();

    const sliceWidth = visualizer.width / bufferLength;
    let x = 0;

    for (let i = 0; i < bufferLength; i++) {
      const v = dataArray[i] / 128.0;
      const y = v * visualizer.height / 2;

      if (i === 0) {
        visualizerCtx.moveTo(x, y);
      } else {
        visualizerCtx.lineTo(x, y);
      }
      x += sliceWidth;
    }

    visualizerCtx.lineTo(visualizer.width, visualizer.height / 2);
    visualizerCtx.stroke();

    animationId = requestAnimationFrame(drawVisualizer);
  }

  // Record audio
  async function startRecording() {
    try {
      const deviceId = micSelect.value;
      const constraints = {
        audio: deviceId ? { deviceId: { exact: deviceId } } : true
      };

      audioStream = await navigator.mediaDevices.getUserMedia(constraints);

      audioContext = new (window.AudioContext || window.webkitAudioContext)();
      analyser = audioContext.createAnalyser();
      const source = audioContext.createMediaStreamSource(audioStream);
      source.connect(analyser);
      analyser.fftSize = 2048;
      drawVisualizer();

      mediaRecorder = new MediaRecorder(audioStream);
      audioChunks = [];

      mediaRecorder.ondataavailable = (e) => audioChunks.push(e.data);

      mediaRecorder.onstop = () => {
        audioBlob = new Blob(audioChunks, { type: 'audio/wav' });
        playBtn.disabled = false;
        recordingStatus.classList.add('d-none');
        updateStatus('success', 'Recording complete! Click "Play Back" to hear your recording.');

        if (animationId) cancelAnimationFrame(animationId);

        testResults.innerHTML = `
          <div class="text-center">
            <i class="bi bi-check-circle text-success fs-1"></i>
            <p class="mt-2">Recording captured successfully.</p>
            <p class="small text-muted">Delay: ${delaySlider.value}ms</p>
          </div>
        `;
      };

      mediaRecorder.start();
      recordBtn.disabled = true;
      recordingStatus.classList.remove('d-none');
      updateStatus('danger', '<i class="bi bi-record-fill me-1"></i> Recording... Speak into your microphone.');

      // Progress animation
      let progress = 0;
      const progressInterval = setInterval(() => {
        progress += 3.33;
        recordProgress.style.width = `${progress}%`;
        if (progress >= 100) clearInterval(progressInterval);
      }, 100);

      // Stop after 3 seconds
      setTimeout(() => {
        if (mediaRecorder.state !== 'inactive') {
          mediaRecorder.stop();
          audioStream.getTracks().forEach(track => track.stop());
        }
        recordBtn.disabled = false;
      }, 3000);

    } catch (error) {
      updateStatus('danger', 'Error: ' + error.message);
      recordBtn.disabled = false;
    }
  }

  // Play back recording
  function playRecording() {
    if (!audioBlob) return;

    const delay = parseInt(delaySlider.value);

    setTimeout(() => {
      const audioUrl = URL.createObjectURL(audioBlob);
      const audio = new Audio(audioUrl);
      audio.play();
      updateStatus('info', 'Playing back your recording. Listen for any echo or delay issues.');
    }, delay);
  }

  // Toggle live monitoring
  async function toggleMonitoring() {
    if (isMonitoring) {
      stopMonitoring();
      return;
    }

    try {
      const deviceId = micSelect.value;
      const constraints = {
        audio: deviceId ? { deviceId: { exact: deviceId } } : true
      };

      audioStream = await navigator.mediaDevices.getUserMedia(constraints);
      audioContext = new (window.AudioContext || window.webkitAudioContext)();

      monitorSource = audioContext.createMediaStreamSource(audioStream);
      delayNode = audioContext.createDelay(1.0);
      delayNode.delayTime.value = parseInt(monitorDelay.value) / 1000;

      analyser = audioContext.createAnalyser();
      analyser.fftSize = 2048;

      monitorSource.connect(delayNode);
      delayNode.connect(analyser);
      analyser.connect(audioContext.destination);

      drawVisualizer();

      isMonitoring = true;
      monitorBtn.innerHTML = '<i class="bi bi-stop-fill me-2"></i>Stop Monitoring';
      monitorBtn.classList.remove('btn-primary');
      monitorBtn.classList.add('btn-danger');
      updateStatus('warning', '<i class="bi bi-broadcast me-1"></i> Live monitoring active. Use headphones to avoid feedback!');

    } catch (error) {
      updateStatus('danger', 'Error: ' + error.message);
    }
  }

  function stopMonitoring() {
    if (audioStream) {
      audioStream.getTracks().forEach(track => track.stop());
    }
    if (audioContext) {
      audioContext.close();
    }
    if (animationId) {
      cancelAnimationFrame(animationId);
    }

    isMonitoring = false;
    monitorBtn.innerHTML = '<i class="bi bi-broadcast me-2"></i>Start Monitoring';
    monitorBtn.classList.remove('btn-danger');
    monitorBtn.classList.add('btn-primary');
    updateStatus('info', 'Monitoring stopped.');
  }

  // Event listeners
  recordBtn.addEventListener('click', startRecording);
  playBtn.addEventListener('click', playRecording);
  monitorBtn.addEventListener('click', toggleMonitoring);

  delaySlider.addEventListener('input', () => {
    delayValue.textContent = `${delaySlider.value}ms`;
  });

  monitorDelay.addEventListener('input', () => {
    monitorDelayValue.textContent = `${monitorDelay.value}ms`;
    if (delayNode) {
      delayNode.delayTime.value = parseInt(monitorDelay.value) / 1000;
    }
  });

  // Initialize
  getAudioDevices();
});

