document.addEventListener('DOMContentLoaded', function () {
  // DOM Elements
  const browserAlert = document.getElementById('browser-alert');
  const browserMessage = document.getElementById('browser-message');
  const devicesContainer = document.getElementById('devices-container');
  const deviceDetails = document.getElementById('device-details');
  const refreshButton = document.getElementById('refresh-button');
  const testButton = document.getElementById('test-button');
  const stopButton = document.getElementById('stop-button');
  const waveform = document.getElementById('waveform');
  const testTypeSelect = document.getElementById('test-type');
  const frequencyControls = document.getElementById('frequency-controls');
  const frequencySelector = document.getElementById('frequency-selector');
  const volumeControl = document.getElementById('volume-control');
  const volumeValue = document.getElementById('volume-value');

  // Variables for audio handling
  let audioContext;
  let oscillator;
  let gainNode;
  let analyser;
  let waveformCtx;
  let activeDeviceId = null;
  let animationFrame = null;
  let testType = 'tone';
  let sweepInterval = null;
  let audioSinkId = null;
  let audioElement = null;

  // Initialize the canvas
  waveformCtx = waveform.getContext('2d');

  // Function to resize the canvas
  function resizeCanvas() {
    waveform.width = waveform.offsetWidth;
    waveform.height = waveform.offsetHeight;
  }

  // Call resize initially and on window resize
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  // Event listener for volume control
  volumeControl.addEventListener('input', function () {
    const value = this.value;
    volumeValue.textContent = value + '%';

    if (gainNode) {
      gainNode.gain.value = value / 100;
    }

    if (audioElement) {
      audioElement.volume = value / 100;
    }
  });

  // Event listener for test type change
  testTypeSelect.addEventListener('change', function () {
    testType = this.value;
    if (testType === 'tone') {
      frequencyControls.classList.remove('d-none');
    } else {
      frequencyControls.classList.add('d-none');
    }
  });

  // Check browser compatibility for media devices
  if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) {
    browserMessage.innerHTML = `
                  <i class="bi bi-exclamation-triangle-fill me-2 text-danger"></i>
                  Your browser doesn't support the required features to detect audio devices. Please use a modern browser like Chrome, Firefox, or Edge.
              `;
    browserAlert.classList.remove('alert-info');
    browserAlert.classList.add('alert-danger');
    return;
  }

  // Function to fetch and display all audio output devices
  function getAudioDevices() {
    browserMessage.innerHTML = `
                  <i class="bi bi-info-circle-fill me-2"></i>
                  Detecting your speakers and audio output devices. Please wait...
              `;

    // Clear existing devices
    devicesContainer.innerHTML = '';

    // Enumerate devices
    navigator.mediaDevices.enumerateDevices()
      .then(devices => {
        const speakers = devices.filter(device => device.kind === 'audiooutput');

        if (speakers.length === 0) {
          displayNoSpeakers();
          return;
        }

        browserMessage.innerHTML = `
                          <i class="bi bi-check-circle-fill me-2 text-success"></i>
                          Found ${speakers.length} speaker${speakers.length > 1 ? 's' : ''}/audio output device${speakers.length > 1 ? 's' : ''}. Click on a device to view detailed information.
                      `;
        browserAlert.classList.remove('alert-info');
        browserAlert.classList.add('alert-success');

        displayDevices(speakers);
      })
      .catch(error => {
        console.error('Error enumerating devices:', error);
        browserMessage.innerHTML = `
                          <i class="bi bi-exclamation-triangle-fill me-2 text-danger"></i>
                          Error accessing your audio devices: ${error.message}.
                      `;
        browserAlert.classList.remove('alert-info');
        browserAlert.classList.add('alert-danger');
      });
  }

  // Function to display no speakers message
  function displayNoSpeakers() {
    devicesContainer.innerHTML = `
                  <div class="col-12">
                      <div class="no-speakers">
                          <i class="bi bi-speaker-x"></i>
                          <h4>No Speakers Detected</h4>
                          <p>We couldn't find any speakers or audio output devices connected to your device. Please connect speakers and click the Refresh button.</p>
                      </div>
                  </div>
              `;

    browserMessage.innerHTML = `
                  <i class="bi bi-exclamation-triangle-fill me-2 text-warning"></i>
                  No speakers detected. Please connect speakers and refresh.
              `;
    browserAlert.classList.remove('alert-info');
    browserAlert.classList.add('alert-warning');

    // Hide device details
    deviceDetails.classList.add('d-none');
  }

  // Function to display found devices
  function displayDevices(speakers) {
    // Create card for each device
    speakers.forEach((device, index) => {
      const deviceCard = document.createElement('div');
      deviceCard.className = 'col-md-4';
      deviceCard.innerHTML = `
                      <div class="card device-card" data-device-id="${device.deviceId}">
                          <div class="card-body">
                              <h5 class="card-title">
                                  <span class="status-dot connected"></span>
                                  ${device.label || `Speaker ${index + 1}`}
                              </h5>
                              <p class="card-text text-muted">
                                  ${device.deviceId.substring(0, 8)}...
                              </p>
                              <button class="btn btn-outline-primary btn-sm view-details-btn">
                                  <i class="bi bi-info-circle me-1"></i>View Details
                              </button>
                          </div>
                      </div>
                  `;
      devicesContainer.appendChild(deviceCard);

      // Add click event to the card
      const card = deviceCard.querySelector('.device-card');
      card.addEventListener('click', () => {
        // Remove selected class from all cards
        document.querySelectorAll('.device-card').forEach(c => {
          c.classList.remove('selected');
        });

        // Add selected class to this card
        card.classList.add('selected');

        // Show device details
        showDeviceDetails(device);
      });
    });
  }

  // Function to show device details
  function showDeviceDetails(device) {
    // Set active device ID
    activeDeviceId = device.deviceId;
    audioSinkId = device.deviceId;

    // Show the details card
    deviceDetails.classList.remove('d-none');

    // Update the device name
    document.getElementById('selected-device-name').textContent = device.label || 'Unknown Speaker';

    // Update basic info
    document.getElementById('device-id').textContent = device.deviceId;
    document.getElementById('group-id').textContent = device.groupId;
    document.getElementById('is-default').textContent = 'Checking...';
    document.getElementById('device-status').innerHTML = '<span class="status-dot connected"></span> Connected';

    // Get information about device quality
    getDeviceDetails(device);
  }

  // Function to get detailed device information
  function getDeviceDetails(device) {
    // Reset all fields first
    document.getElementById('sample-rate').textContent = '—';
    document.getElementById('sample-size').textContent = '—';
    document.getElementById('channel-count').textContent = '—';
    document.getElementById('latency').textContent = '—';
    document.getElementById('audio-format').textContent = '—';
    document.getElementById('quality-rating').textContent = '—';

    // Try to get some estimated specs based on the device label
    const label = device.label.toLowerCase();

    // Check if this is the default device
    navigator.mediaDevices.enumerateDevices()
      .then(devices => {
        const audioOutputs = devices.filter(d => d.kind === 'audiooutput');

        if (audioOutputs.length > 0 && audioOutputs[0].deviceId === device.deviceId) {
          document.getElementById('is-default').innerHTML = '<span class="status-dot default"></span> Default Device';
        } else {
          document.getElementById('is-default').innerHTML = 'Not Default';
        }
      });

    // For many browsers/systems, we can't directly query detailed specs for output devices
    // So we'll make educated guesses based on the device name and typical specs

    // Sample rate - most modern audio devices support at least 44.1 kHz
    document.getElementById('sample-rate').textContent = '44.1/48 kHz (typical)';

    // Channel count - guess based on device name
    let channels = 2; // Default to stereo
    if (label.includes('surround') || label.includes('5.1') || label.includes('7.1')) {
      channels = label.includes('5.1') ? 6 : label.includes('7.1') ? 8 : 'Multiple';
      document.getElementById('channel-count').textContent = channels + ' channels (surround)';
    } else if (label.includes('mono')) {
      channels = 1;
      document.getElementById('channel-count').textContent = '1 channel (mono)';
    } else {
      document.getElementById('channel-count').textContent = '2 channels (stereo)';
    }

    // Sample size - typical for modern audio
    document.getElementById('sample-size').textContent = '16/24 bit (typical)';

    // Latency - we don't know exactly
    document.getElementById('latency').textContent = 'Varies by system';

    // Audio format
    let format = 'PCM';
    if (label.includes('dolby') || label.includes('atmos')) {
      format = 'Dolby Digital/Atmos compatible';
    } else if (label.includes('dts')) {
      format = 'DTS compatible';
    }
    document.getElementById('audio-format').textContent = format;

    // Calculate quality rating
    let qualityScore = 0;
    if (channels > 2) qualityScore += 1;
    if (label.includes('studio') || label.includes('pro')) qualityScore += 1;
    if (label.includes('hi-fi') || label.includes('high fidelity')) qualityScore += 1;
    if (label.includes('bluetooth')) qualityScore -= 0.5;
    if (label.includes('dolby') || label.includes('atmos') || label.includes('dts')) qualityScore += 1;
    if (label.includes('built-in') || label.includes('internal')) qualityScore -= 0.5;

    let qualityRating;
    let qualityClass;

    if (qualityScore >= 2) {
      qualityRating = 'High-End';
      qualityClass = 'text-success';
    } else if (qualityScore >= 1) {
      qualityRating = 'Very Good';
      qualityClass = 'text-primary';
    } else if (qualityScore >= 0) {
      qualityRating = 'Standard';
      qualityClass = 'text-info';
    } else {
      qualityRating = 'Basic';
      qualityClass = 'text-warning';
    }

    // Note: This is an educated guess since we can't directly query all speaker capabilities
    document.getElementById('quality-rating').innerHTML = `
                  <span class="${qualityClass}">${qualityRating}</span>
                  <small class="text-muted ms-2">(estimated based on device type)</small>
              `;
  }

  // Function to test the speaker
  function testSpeaker() {
    if (!activeDeviceId) {
      alert('Please select a speaker first');
      return;
    }

    // Swap buttons
    testButton.classList.add('d-none');
    stopButton.classList.remove('d-none');

    // Initialize audio context (wait until user interaction)
    if (!audioContext) {
      window.AudioContext = window.AudioContext || window.webkitAudioContext;
      audioContext = new AudioContext();
    }

    // Create audio nodes
    analyser = audioContext.createAnalyser();
    analyser.fftSize = 2048;

    gainNode = audioContext.createGain();
    gainNode.gain.value = volumeControl.value / 100;

    gainNode.connect(analyser);
    analyser.connect(audioContext.destination);

    // Different test types
    switch (testType) {
      case 'tone':
        playTone();
        break;
      case 'sweep':
        playSweep();
        break;
      case 'white-noise':
        playWhiteNoise();
        break;
      case 'left-right':
        playLeftRightTest();
        break;
    }

    // Start visualization
    visualize();
  }

  // Function to play a simple tone
  function playTone() {
    oscillator = audioContext.createOscillator();
    oscillator.type = 'sine';
    oscillator.frequency.value = parseFloat(frequencySelector.value);
    oscillator.connect(gainNode);
    oscillator.start();
  }

  // Function to play a frequency sweep
  function playSweep() {
    oscillator = audioContext.createOscillator();
    oscillator.type = 'sine';
    oscillator.frequency.value = 100; // Start at 100Hz
    oscillator.connect(gainNode);
    oscillator.start();

    // Sweep the frequency
    let frequency = 100;
    const maxFrequency = 12000;
    const step = 10;

    sweepInterval = setInterval(() => {
      frequency += step;
      if (frequency > maxFrequency) {
        frequency = 100; // Reset to beginning
      }

      oscillator.frequency.value = frequency;
    }, 30);
  }

  // Function to play white noise
  function playWhiteNoise() {
    const bufferSize = 2 * audioContext.sampleRate;
    const noiseBuffer = audioContext.createBuffer(2, bufferSize, audioContext.sampleRate);

    // Fill buffer with white noise
    for (let channel = 0; channel < 2; channel++) {
      const buffer = noiseBuffer.getChannelData(channel);
      for (let i = 0; i < bufferSize; i++) {
        buffer[i] = Math.random() * 2 - 1;
      }
    }

    // Create source from buffer and connect
    const noiseSource = audioContext.createBufferSource();
    noiseSource.buffer = noiseBuffer;
    noiseSource.loop = true;
    noiseSource.connect(gainNode);
    noiseSource.start();

    // Store the source for stopping later
    oscillator = noiseSource;
  }

  // Function to play left/right channel test
  function playLeftRightTest() {
    // Create audio element for stereo control
    audioElement = document.createElement('audio');
    audioElement.controls = false;

    // Get access to the audio track
    const audioData = {
      leftChannel: createAudioTestTone('left'),
      rightChannel: createAudioTestTone('right')
    };

    // Create source from audio element
    const source = audioContext.createMediaElementSource(audioElement);
    source.connect(gainNode);

    // Set audio element properties
    audioElement.volume = volumeControl.value / 100;
    audioElement.loop = true;

    // Set the sink ID if supported
    if (typeof audioElement.setSinkId === 'function') {
      audioElement.setSinkId(audioSinkId)
        .then(() => {
          console.log('Audio output device set successfully');
        })
        .catch(err => {
          console.error('Error setting audio output device:', err);
        });
    }

    // Create a blob URL and play
    const blob = new Blob([audioData.leftChannel, audioData.rightChannel], {type: 'audio/wav'});
    audioElement.src = URL.createObjectURL(blob);
    audioElement.play();
  }

  // Helper function to create test tones for left/right channels
  function createAudioTestTone(channel) {
    // This is a simplified representation - in a real app, you'd need to create an actual WAV file
    // with proper headers and stereo channel data
    console.log(`Creating test tone for ${channel} channel`);
    return new ArrayBuffer(1024); // Placeholder
  }

  // Function to visualize audio
  function visualize() {
    if (!analyser) return;

    // Get the canvas dimensions
    const width = waveform.width;
    const height = waveform.height;

    // Set up the analyzer
    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    // Clear the canvas
    waveformCtx.clearRect(0, 0, width, height);
    waveformCtx.fillStyle = 'rgb(248, 249, 250)';
    waveformCtx.fillRect(0, 0, width, height);

    function draw() {
      if (!analyser) {
        return;
      }

      // Request next frame
      animationFrame = requestAnimationFrame(draw);

      // Get time domain data for waveform
      analyser.getByteTimeDomainData(dataArray);

      // Clear canvas
      waveformCtx.clearRect(0, 0, width, height);
      waveformCtx.fillStyle = 'rgb(248, 249, 250)';
      waveformCtx.fillRect(0, 0, width, height);

      // Draw waveform
      waveformCtx.lineWidth = 2;
      waveformCtx.strokeStyle = 'rgb(13, 110, 253)';
      waveformCtx.beginPath();

      const sliceWidth = width / bufferLength;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const v = dataArray[i] / 128.0;
        const y = v * height / 2;

        if (i === 0) {
          waveformCtx.moveTo(x, y);
        } else {
          waveformCtx.lineTo(x, y);
        }

        x += sliceWidth;
      }

      waveformCtx.lineTo(width, height / 2);
      waveformCtx.stroke();
    }

    draw();
  }

  // Function to stop speaker test
  function stopSpeakerTest() {
    // Cancel animation frame
    if (animationFrame) {
      cancelAnimationFrame(animationFrame);
      animationFrame = null;
    }

    // Clear interval for frequency sweep
    if (sweepInterval) {
      clearInterval(sweepInterval);
      sweepInterval = null;
    }

    // Stop oscillator
    if (oscillator) {
      oscillator.stop();
      oscillator.disconnect();
      oscillator = null;
    }

    // Stop audio element
    if (audioElement) {
      audioElement.pause();
      audioElement.src = '';
      audioElement = null;
    }

    // Clean up audio nodes
    if (gainNode) {
      gainNode.disconnect();
      gainNode = null;
    }

    if (analyser) {
      analyser.disconnect();
      analyser = null;
    }

    // Reset buttons
    stopButton.classList.add('d-none');
    testButton.classList.remove('d-none');

    // Clear canvas
    waveformCtx.clearRect(0, 0, waveform.width, waveform.height);
    waveformCtx.fillStyle = 'rgb(248, 249, 250)';
    waveformCtx.fillRect(0, 0, waveform.width, waveform.height);
  }

  // Event listeners
  refreshButton.addEventListener('click', getAudioDevices);
  testButton.addEventListener('click', testSpeaker);
  stopButton.addEventListener('click', stopSpeakerTest);

  // Initialize
  getAudioDevices();
});

document.addEventListener('DOMContentLoaded', function() {
  const freqSlider = document.getElementById('freq-slider');
  const freqInput = document.getElementById('freq-input');
  const freqDisplay = document.getElementById('freq-display');
  const noteDisplay = document.getElementById('note-display');
  const volumeSlider = document.getElementById('volume-slider');
  const volumeDisplay = document.getElementById('volume-display');
  const playBtn = document.getElementById('play-btn');
  const visualizer = document.getElementById('visualizer');
  const visualizerCtx = visualizer.getContext('2d');
  const waveformBtns = document.querySelectorAll('.waveform-btn');
  const presetBtns = document.querySelectorAll('.preset-btn');
  const whiteNoiseBtn = document.getElementById('white-noise-btn');
  const pinkNoiseBtn = document.getElementById('pink-noise-btn');
  const leftOnlyBtn = document.getElementById('left-only-btn');
  const rightOnlyBtn = document.getElementById('right-only-btn');
  const bothBtn = document.getElementById('both-btn');

  let audioContext = null;
  let oscillator = null;
  let gainNode = null;
  let analyser = null;
  let isPlaying = false;
  let waveformType = 'sine';
  let panValue = 0;
  let panNode = null;
  let animationId = null;

  const noteNames = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

  function resizeCanvas() {
    visualizer.width = visualizer.parentElement.offsetWidth;
    visualizer.height = visualizer.parentElement.offsetHeight;
  }
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  function freqToNote(freq) {
    const noteNum = 12 * (Math.log2(freq / 440)) + 69;
    const octave = Math.floor((noteNum - 12) / 12);
    const noteIndex = Math.round(noteNum) % 12;
    return noteNames[noteIndex] + octave;
  }

  function updateFrequencyDisplay(freq) {
    freqDisplay.textContent = Math.round(freq);
    noteDisplay.textContent = freqToNote(freq);
    freqSlider.value = freq;
    freqInput.value = Math.round(freq);

    if (oscillator && isPlaying) {
      oscillator.frequency.setValueAtTime(freq, audioContext.currentTime);
    }
  }

  function drawVisualizer() {
    if (!analyser) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    analyser.getByteTimeDomainData(dataArray);

    visualizerCtx.fillStyle = '#1a1a2e';
    visualizerCtx.fillRect(0, 0, visualizer.width, visualizer.height);

    visualizerCtx.lineWidth = 2;
    visualizerCtx.strokeStyle = '#00ff88';
    visualizerCtx.beginPath();

    const sliceWidth = visualizer.width / bufferLength;
    let x = 0;

    for (let i = 0; i < bufferLength; i++) {
      const v = dataArray[i] / 128.0;
      const y = v * visualizer.height / 2;

      if (i === 0) visualizerCtx.moveTo(x, y);
      else visualizerCtx.lineTo(x, y);
      x += sliceWidth;
    }

    visualizerCtx.lineTo(visualizer.width, visualizer.height / 2);
    visualizerCtx.stroke();

    animationId = requestAnimationFrame(drawVisualizer);
  }

  function startTone() {
    if (!audioContext) {
      audioContext = new (window.AudioContext || window.webkitAudioContext)();
    }

    if (isPlaying) {
      stopTone();
      return;
    }

    oscillator = audioContext.createOscillator();
    gainNode = audioContext.createGain();
    analyser = audioContext.createAnalyser();
    panNode = audioContext.createStereoPanner();

    oscillator.type = waveformType;
    oscillator.frequency.setValueAtTime(parseFloat(freqInput.value), audioContext.currentTime);
    gainNode.gain.setValueAtTime(volumeSlider.value / 100 * 0.5, audioContext.currentTime);
    panNode.pan.setValueAtTime(panValue, audioContext.currentTime);
    analyser.fftSize = 2048;

    oscillator.connect(gainNode);
    gainNode.connect(panNode);
    panNode.connect(analyser);
    analyser.connect(audioContext.destination);

    oscillator.start();
    isPlaying = true;

    playBtn.innerHTML = '<i class="bi bi-stop-fill me-2"></i>Stop';
    playBtn.classList.remove('btn-success');
    playBtn.classList.add('btn-danger');

    drawVisualizer();
  }

  function stopTone() {
    if (oscillator) {
      oscillator.stop();
      oscillator.disconnect();
      oscillator = null;
    }
    if (animationId) {
      cancelAnimationFrame(animationId);
    }

    isPlaying = false;
    playBtn.innerHTML = '<i class="bi bi-play-fill me-2"></i>Play Tone';
    playBtn.classList.remove('btn-danger');
    playBtn.classList.add('btn-success');

    // Clear visualizer
    visualizerCtx.fillStyle = '#1a1a2e';
    visualizerCtx.fillRect(0, 0, visualizer.width, visualizer.height);
  }

  function playNoise(type) {
    if (!audioContext) {
      audioContext = new (window.AudioContext || window.webkitAudioContext)();
    }

    stopTone();

    const bufferSize = 2 * audioContext.sampleRate;
    const noiseBuffer = audioContext.createBuffer(2, bufferSize, audioContext.sampleRate);

    for (let channel = 0; channel < 2; channel++) {
      const nowBuffering = noiseBuffer.getChannelData(channel);
      for (let i = 0; i < bufferSize; i++) {
        if (type === 'white') {
          nowBuffering[i] = Math.random() * 2 - 1;
        } else {
          // Pink noise approximation
          let white = Math.random() * 2 - 1;
          nowBuffering[i] = (nowBuffering[i - 1] || 0) * 0.99 + white * 0.01;
        }
      }
    }

    const noiseSource = audioContext.createBufferSource();
    noiseSource.buffer = noiseBuffer;
    noiseSource.loop = true;

    gainNode = audioContext.createGain();
    analyser = audioContext.createAnalyser();

    gainNode.gain.setValueAtTime(volumeSlider.value / 100 * 0.3, audioContext.currentTime);
    analyser.fftSize = 2048;

    noiseSource.connect(gainNode);
    gainNode.connect(analyser);
    analyser.connect(audioContext.destination);

    noiseSource.start();
    oscillator = noiseSource;
    isPlaying = true;

    playBtn.innerHTML = '<i class="bi bi-stop-fill me-2"></i>Stop';
    playBtn.classList.remove('btn-success');
    playBtn.classList.add('btn-danger');

    drawVisualizer();
  }

  // Event listeners
  playBtn.addEventListener('click', startTone);

  freqSlider.addEventListener('input', () => updateFrequencyDisplay(freqSlider.value));
  freqInput.addEventListener('change', () => {
    const val = Math.max(20, Math.min(20000, freqInput.value));
    updateFrequencyDisplay(val);
  });

  volumeSlider.addEventListener('input', () => {
    volumeDisplay.textContent = volumeSlider.value + '%';
    if (gainNode) {
      gainNode.gain.setValueAtTime(volumeSlider.value / 100 * 0.5, audioContext.currentTime);
    }
  });

  waveformBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      waveformBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      waveformType = btn.dataset.wave;
      if (isPlaying) {
        stopTone();
        startTone();
      }
    });
  });

  presetBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      updateFrequencyDisplay(parseFloat(btn.dataset.freq));
    });
  });

  whiteNoiseBtn.addEventListener('click', () => playNoise('white'));
  pinkNoiseBtn.addEventListener('click', () => playNoise('pink'));

  leftOnlyBtn.addEventListener('click', () => {
    panValue = -1;
    if (panNode) panNode.pan.setValueAtTime(-1, audioContext.currentTime);
  });
  rightOnlyBtn.addEventListener('click', () => {
    panValue = 1;
    if (panNode) panNode.pan.setValueAtTime(1, audioContext.currentTime);
  });
  bothBtn.addEventListener('click', () => {
    panValue = 0;
    if (panNode) panNode.pan.setValueAtTime(0, audioContext.currentTime);
  });
});

