script:
document.addEventListener('DOMContentLoaded', function() {
  const leftChannel = document.getElementById('left-channel');
  const rightChannel = document.getElementById('right-channel');
  const leftIcon = document.getElementById('left-icon');
  const rightIcon = document.getElementById('right-icon');
  const playLeftBtn = document.getElementById('play-left-btn');
  const playRightBtn = document.getElementById('play-right-btn');
  const playBothBtn = document.getElementById('play-both-btn');
  const stopBtn = document.getElementById('stop-btn');
  const balanceSlider = document.getElementById('balance-slider');
  const balanceValue = document.getElementById('balance-value');
  const balanceLeft = document.getElementById('balance-left');
  const balanceCenter = document.getElementById('balance-center');
  const balanceRight = document.getElementById('balance-right');
  const frequencySelect = document.getElementById('frequency-select');
  const volumeSlider = document.getElementById('volume-slider');
  const volumeDisplay = document.getElementById('volume-display');
  const autoTestBtn = document.getElementById('auto-test-btn');

  let audioContext = null;
  let oscillator = null;
  let gainNode = null;
  let panNode = null;
  let isPlaying = false;
  let autoTestInterval = null;

  function initAudio() {
    if (!audioContext) {
      audioContext = new (window.AudioContext || window.webkitAudioContext)();
    }
  }

  function playTone(pan = 0) {
    initAudio();
    stopTone();

    oscillator = audioContext.createOscillator();
    gainNode = audioContext.createGain();
    panNode = audioContext.createStereoPanner();

    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(parseInt(frequencySelect.value), audioContext.currentTime);
    gainNode.gain.setValueAtTime(volumeSlider.value / 100 * 0.5, audioContext.currentTime);
    panNode.pan.setValueAtTime(pan, audioContext.currentTime);

    oscillator.connect(gainNode);
    gainNode.connect(panNode);
    panNode.connect(audioContext.destination);

    oscillator.start();
    isPlaying = true;
    stopBtn.disabled = false;

    updateChannelIndicators(pan);
  }

  function stopTone() {
    if (oscillator) {
      oscillator.stop();
      oscillator.disconnect();
      oscillator = null;
    }
    isPlaying = false;
    stopBtn.disabled = true;

    leftChannel.classList.remove('playing');
    rightChannel.classList.remove('playing');
    leftIcon.classList.remove('active');
    rightIcon.classList.remove('active');
  }

  function updateChannelIndicators(pan) {
    leftChannel.classList.remove('playing');
    rightChannel.classList.remove('playing');
    leftIcon.classList.remove('active');
    rightIcon.classList.remove('active');

    if (pan <= 0) {
      leftChannel.classList.add('playing');
      leftIcon.classList.add('active');
    }
    if (pan >= 0) {
      rightChannel.classList.add('playing');
      rightIcon.classList.add('active');
    }
  }

  function updateBalance(value) {
    balanceSlider.value = value;
    if (value < -10) {
      balanceValue.textContent = 'Left ' + Math.abs(value) + '%';
    } else if (value > 10) {
      balanceValue.textContent = 'Right ' + value + '%';
    } else {
      balanceValue.textContent = 'Center';
    }

    if (panNode && isPlaying) {
      panNode.pan.setValueAtTime(value / 100, audioContext.currentTime);
      updateChannelIndicators(value / 100);
    }
  }

  async function runAutoTest() {
    if (autoTestInterval) {
      clearInterval(autoTestInterval);
      autoTestInterval = null;
      stopTone();
      autoTestBtn.innerHTML = '<i class="bi bi-play-fill me-2"></i>Run Automatic Test';
      document.querySelectorAll('.test-sequence-item').forEach(item => item.classList.remove('active'));
      return;
    }

    autoTestBtn.innerHTML = '<i class="bi bi-stop-fill me-2"></i>Stop Test';
    const steps = [
      { pan: -1, duration: 2000, step: 1 },
      { pan: 1, duration: 2000, step: 2 },
      { pan: -1, duration: 500, step: 3 },
      { pan: 1, duration: 500, step: 3 },
      { pan: -1, duration: 500, step: 3 },
      { pan: 1, duration: 500, step: 3 },
      { pan: -1, duration: 500, step: 3 },
      { pan: 1, duration: 500, step: 3 },
      { pan: -1, duration: 500, step: 3 },
      { pan: 1, duration: 500, step: 3 },
      { pan: 0, duration: 2000, step: 4 }
    ];

    let currentStep = 0;

    function nextStep() {
      if (currentStep >= steps.length) {
        stopTone();
        autoTestBtn.innerHTML = '<i class="bi bi-play-fill me-2"></i>Run Automatic Test';
        document.querySelectorAll('.test-sequence-item').forEach(item => item.classList.remove('active'));
        autoTestInterval = null;
        return;
      }

      const step = steps[currentStep];
      document.querySelectorAll('.test-sequence-item').forEach(item => {
        item.classList.toggle('active', item.dataset.step == step.step);
      });

      playTone(step.pan);
      currentStep++;
      autoTestInterval = setTimeout(nextStep, step.duration);
    }

    nextStep();
  }

  // Event listeners
  leftChannel.addEventListener('click', () => playTone(-1));
  rightChannel.addEventListener('click', () => playTone(1));

  [leftChannel, rightChannel].forEach(function(el) {
    el.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); el.click(); }
    });
  });
  playLeftBtn.addEventListener('click', () => playTone(-1));
  playRightBtn.addEventListener('click', () => playTone(1));
  playBothBtn.addEventListener('click', () => playTone(0));
  stopBtn.addEventListener('click', stopTone);

  balanceSlider.addEventListener('input', () => updateBalance(parseInt(balanceSlider.value)));
  balanceLeft.addEventListener('click', () => updateBalance(-100));
  balanceCenter.addEventListener('click', () => updateBalance(0));
  balanceRight.addEventListener('click', () => updateBalance(100));

  volumeSlider.addEventListener('input', () => {
    volumeDisplay.textContent = volumeSlider.value + '%';
    if (gainNode && isPlaying) {
      gainNode.gain.setValueAtTime(volumeSlider.value / 100 * 0.5, audioContext.currentTime);
    }
  });

  frequencySelect.addEventListener('change', () => {
    if (isPlaying) {
      oscillator.frequency.setValueAtTime(parseInt(frequencySelect.value), audioContext.currentTime);
    }
  });

  autoTestBtn.addEventListener('click', runAutoTest);
});

