script:
document.addEventListener('DOMContentLoaded', function() {
  const freqBtns = document.querySelectorAll('.freq-btn');
  const earSelect = document.getElementById('ear-select');
  const volume = document.getElementById('volume');
  const volDisplay = document.getElementById('vol-display');
  const duration = document.getElementById('duration');
  const heardBtn = document.getElementById('heard-btn');
  const notHeardBtn = document.getElementById('not-heard-btn');
  const resetBtn = document.getElementById('reset-btn');
  const rangeDisplay = document.getElementById('range-display');
  const rangeComment = document.getElementById('range-comment');
  const lowMarker = document.getElementById('low-marker');
  const highMarker = document.getElementById('high-marker');

  let audioContext = null;
  let oscillator = null;
  let currentBtn = null;
  let results = {};

  function playTone(freq) {
    stopTone();
    if (!audioContext) audioContext = new (window.AudioContext || window.webkitAudioContext)();

    oscillator = audioContext.createOscillator();
    const gainNode = audioContext.createGain();
    const panNode = audioContext.createStereoPanner();

    oscillator.frequency.setValueAtTime(freq, audioContext.currentTime);
    gainNode.gain.setValueAtTime(volume.value / 100 * 0.3, audioContext.currentTime);

    const ear = earSelect.value;
    panNode.pan.setValueAtTime(ear === 'left' ? -1 : ear === 'right' ? 1 : 0, audioContext.currentTime);

    oscillator.connect(gainNode);
    gainNode.connect(panNode);
    panNode.connect(audioContext.destination);
    oscillator.start();

    const dur = parseFloat(duration.value) * 1000;
    setTimeout(stopTone, dur);
  }

  function stopTone() {
    if (oscillator) { try { oscillator.stop(); } catch(e) {} oscillator = null; }
  }

  function updateRange() {
    const heard = Object.entries(results).filter(([f, h]) => h).map(([f]) => parseInt(f)).sort((a,b) => a-b);
    if (heard.length === 0) {
      rangeDisplay.textContent = '-- Hz to -- Hz';
      rangeComment.textContent = 'Complete the test to see your hearing range';
      return;
    }
    const low = heard[0];
    const high = heard[heard.length - 1];
    rangeDisplay.textContent = `${low} Hz to ${high >= 1000 ? (high/1000) + ' kHz' : high + ' Hz'}`;

    // Position markers (log scale)
    const logPos = (f) => (Math.log10(f) - Math.log10(20)) / (Math.log10(20000) - Math.log10(20)) * 100;
    lowMarker.style.left = logPos(low) + '%';
    highMarker.style.left = logPos(high) + '%';

    if (high >= 16000) rangeComment.textContent = 'Excellent hearing range!';
    else if (high >= 12000) rangeComment.textContent = 'Good hearing range for most adults';
    else if (high >= 8000) rangeComment.textContent = 'Typical for ages 50+';
    else rangeComment.textContent = 'Consider consulting an audiologist';
  }

  freqBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      if (currentBtn) currentBtn.classList.remove('btn-primary');
      currentBtn = btn;
      btn.classList.add('btn-primary');
      playTone(parseInt(btn.dataset.freq));
      heardBtn.disabled = false;
      notHeardBtn.disabled = false;
    });
  });

  heardBtn.addEventListener('click', () => {
    if (!currentBtn) return;
    results[currentBtn.dataset.freq] = true;
    currentBtn.classList.remove('btn-primary', 'btn-outline-primary', 'btn-secondary');
    currentBtn.classList.add('btn-success');
    currentBtn.innerHTML = currentBtn.dataset.freq >= 1000 ?
      (currentBtn.dataset.freq/1000) + ' kHz <span class="heard-badge badge bg-light text-success">✓</span>' :
      currentBtn.dataset.freq + ' Hz <span class="heard-badge badge bg-light text-success">✓</span>';
    updateRange();
    heardBtn.disabled = true;
    notHeardBtn.disabled = true;
  });

  notHeardBtn.addEventListener('click', () => {
    if (!currentBtn) return;
    results[currentBtn.dataset.freq] = false;
    currentBtn.classList.remove('btn-primary', 'btn-outline-primary', 'btn-success');
    currentBtn.classList.add('btn-secondary');
    currentBtn.innerHTML = currentBtn.dataset.freq >= 1000 ?
      (currentBtn.dataset.freq/1000) + ' kHz <span class="heard-badge badge bg-light text-secondary">✗</span>' :
      currentBtn.dataset.freq + ' Hz <span class="heard-badge badge bg-light text-secondary">✗</span>';
    updateRange();
    heardBtn.disabled = true;
    notHeardBtn.disabled = true;
  });

  resetBtn.addEventListener('click', () => {
    results = {};
    freqBtns.forEach(btn => {
      btn.classList.remove('btn-primary', 'btn-success', 'btn-secondary');
      btn.classList.add('btn-outline-primary');
      const freq = parseInt(btn.dataset.freq);
      btn.innerHTML = freq >= 1000 ? (freq/1000) + ' kHz' : freq + ' Hz';
    });
    updateRange();
    currentBtn = null;
    heardBtn.disabled = true;
    notHeardBtn.disabled = true;
  });

  volume.addEventListener('input', () => volDisplay.textContent = volume.value + '%');
});

